var client = new ServiceBusClient(connectionString);
var sender = client.CreateSender("stock-commands");

var message = new ServiceBusMessage(BinaryData.FromObjectAsJson(new
{
    OrderId = orderId,
    Sku = "SKU-1024",
    Quantity = 2
}))
{
    MessageId = Guid.NewGuid().ToString(),   // enables duplicate detection
    ContentType = "application/json",
    SessionId = customerId                  // ordered processing per customer
};

await sender.SendMessageAsync(message);

resource blobSub 'Microsoft.EventGrid/eventSubscriptions@2023-12-15-preview' = {
  name: 'thumbnails-on-upload'
  scope: storageAccount
  properties: {
    destination: {
      endpointType: 'AzureFunction'
      properties: { resourceId: thumbnailFunction.id, maxEventsPerBatch: 10 }
    }
    filter: {
      includedEventTypes: [ 'Microsoft.Storage.BlobCreated' ]
      subjectBeginsWith: '/blobServices/default/containers/uploads/'
    }
    retryPolicy: { maxDeliveryAttempts: 30, eventTimeToLiveInMinutes: 1440 }
  }
}

var producer = new EventHubProducerClient(connectionString, "telemetry");
using var batch = await producer.CreateBatchAsync();

foreach (var reading in readings)
{
    var payload = BinaryData.FromObjectAsJson(reading);
    if (!batch.TryAdd(new EventData(payload) { PartitionKey = reading.DeviceId }))
    {
        await producer.SendAsync(batch);                       // flush full batch
        batch.Dispose();
        batch = await producer.CreateBatchAsync();
        batch.TryAdd(new EventData(payload) { PartitionKey = reading.DeviceId });
    }
}
await producer.SendAsync(batch);
